"""Generated by the QA agent for STORY-002: Deposit and withdraw money."""


def test_tc_002_01_deposit_increases_balance(api):
    """TC-002-01"""
    acc = api.create_account("Laila", 100)
    r = api.post(f"/accounts/{acc['id']}/deposit", json={"amount": 50})
    assert r.status_code == 200, r.text
    assert api.balance(acc["id"]) == 150


def test_tc_002_02_negative_deposit_rejected(api):
    """TC-002-02"""
    acc = api.create_account("Laila", 100)
    r = api.post(f"/accounts/{acc['id']}/deposit", json={"amount": -20})
    assert r.status_code == 422, f"expected 422, got {r.status_code}: {r.text}"
    assert api.balance(acc["id"]) == 100


def test_tc_002_03_zero_deposit_rejected(api):
    """TC-002-03"""
    acc = api.create_account("Laila", 100)
    r = api.post(f"/accounts/{acc['id']}/deposit", json={"amount": 0})
    assert r.status_code == 422, r.text
    assert api.balance(acc["id"]) == 100


def test_tc_002_04_withdrawal_decreases_balance(api):
    """TC-002-04"""
    acc = api.create_account("Karim", 100)
    r = api.post(f"/accounts/{acc['id']}/withdraw", json={"amount": 40})
    assert r.status_code == 200, r.text
    assert api.balance(acc["id"]) == 60


def test_tc_002_05_overdraw_refused(api):
    """TC-002-05"""
    acc = api.create_account("Karim", 100)
    r = api.post(f"/accounts/{acc['id']}/withdraw", json={"amount": 150})
    assert r.status_code == 409, r.text
    assert api.balance(acc["id"]) == 100


def test_tc_002_06_balance_rounded_to_two_decimals(api):
    """TC-002-06"""
    acc = api.create_account("Nour", 0)
    api.post(f"/accounts/{acc['id']}/deposit", json={"amount": 0.10})
    api.post(f"/accounts/{acc['id']}/deposit", json={"amount": 0.20})
    balance = api.balance(acc["id"])
    assert balance == 0.30, f"expected 0.30, got {balance!r}"
